void createMathOperationsDB(map<string, string>& op_) // ñîçäàíèå DB ìàòîïåðàöèé
{
    op_.emplace("io0", "+");
    op_.emplace("io1", "-");
    op_.emplace("io2", "*");
    op_.emplace("io3", "/");
    op_.emplace("io4", "(");
    op_.emplace("io5", ")");
    op_.emplace("io6", "^");
    op_.emplace("io7", "=");
}

